python3 << 'PYEOF'
import xml.etree.ElementTree as ET

NS = {
    'bpmn': 'http://www.omg.org/spec/BPMN/20100524/MODEL',
    'bpmndi': 'http://www.omg.org/spec/BPMN/20100524/DI',
    'uipath': 'http://uipath.org/schema/bpmn',
}

tree = ET.parse('/work/output/artifacts/skill-bpmn-calculator/CalculatorBpmn/CalculatorBpmn.bpmn')
root = tree.getroot()

errors = []

# 1. Root is definitions with BPMN namespace
assert 'http://www.omg.org/spec/BPMN/20100524/MODEL' in root.tag, "Root is not bpmn:definitions"
print("✓ Root is bpmn:definitions")

proc = root.find('bpmn:process', NS)
assert proc is not None, "No bpmn:process found"
print("✓ bpmn:process present")

# Collect all element IDs
ids = {el.get('id') for el in root.iter() if el.get('id')}
print(f"✓ {len(ids)} elements with IDs")

# 2. Check BPMNDiagram shapes and edges
diagram = root.find('bpmndi:BPMNDiagram', NS)
assert diagram is not None, "No BPMNDiagram"
plane = diagram.find('bpmndi:BPMNPlane', NS)
assert plane is not None, "No BPMNPlane"

shapes = {s.get('bpmnElement') for s in plane.findall('bpmndi:BPMNShape', NS)}
edges  = {e.get('bpmnElement') for e in plane.findall('bpmndi:BPMNEdge', NS)}

# Collect flow node IDs and sequence flow IDs
flow_nodes = set()
for tag in ['startEvent','endEvent','exclusiveGateway','scriptTask']:
    for el in proc.findall(f'bpmn:{tag}', NS):
        flow_nodes.add(el.get('id'))

seq_flows = {el.get('id') for el in proc.findall('bpmn:sequenceFlow', NS)}

missing_shapes = flow_nodes - shapes
missing_edges  = seq_flows - edges
if missing_shapes:
    errors.append(f"Nodes missing BPMNShape: {missing_shapes}")
else:
    print(f"✓ All {len(flow_nodes)} flow nodes have BPMNShape")
if missing_edges:
    errors.append(f"Flows missing BPMNEdge: {missing_edges}")
else:
    print(f"✓ All {len(seq_flows)} sequence flows have BPMNEdge")

# 3. sourceRef/targetRef all resolve
for sf in proc.findall('bpmn:sequenceFlow', NS):
    src = sf.get('sourceRef')
    tgt = sf.get('targetRef')
    if src not in ids: errors.append(f"sourceRef {src!r} not found")
    if tgt not in ids: errors.append(f"targetRef {tgt!r} not found")
print("✓ All sourceRef/targetRef resolve")

# 4. Exclusive gateway: non-default flows have conditions; exactly one default
for gw in proc.findall('bpmn:exclusiveGateway', NS):
    default_id = gw.get('default')
    outgoing = [el.text.strip() for el in gw.findall('bpmn:outgoing', NS)]
    assert default_id, f"Gateway {gw.get('id')} has no default"
    assert default_id in outgoing, f"default {default_id} not in outgoing {outgoing}"
    for sf in proc.findall('bpmn:sequenceFlow', NS):
        if sf.get('id') in outgoing and sf.get('id') != default_id:
            cond = sf.find('bpmn:conditionExpression', NS)
            if cond is None:
                errors.append(f"Non-default flow {sf.get('id')} has no conditionExpression")
    default_sf = next(sf for sf in proc.findall('bpmn:sequenceFlow', NS) if sf.get('id') == default_id)
    cond_on_default = default_sf.find('bpmn:conditionExpression', NS)
    if cond_on_default is not None:
        errors.append(f"Default flow {default_id} should not have conditionExpression")
print("✓ Exclusive gateway conditions/default OK")

# 5. No activity/event has more than one incoming flow
incoming_count = {}
for sf in proc.findall('bpmn:sequenceFlow', NS):
    tgt = sf.get('targetRef')
    incoming_count[tgt] = incoming_count.get(tgt, 0) + 1
for node_id, cnt in incoming_count.items():
    if cnt > 1:
        errors.append(f"FAKE_JOIN: node {node_id} has {cnt} incoming flows")
print("✓ No fake-join (all nodes have at most 1 incoming flow)")

# 6. Script tasks have scriptVersion v3
for st in proc.findall('bpmn:scriptTask', NS):
    ext = st.find('bpmn:extensionElements', NS)
    sv = ext.find('uipath:scriptVersion', NS) if ext is not None else None
    if sv is None or sv.get('value') != 'v3':
        errors.append(f"scriptTask {st.get('id')} missing scriptVersion v3")
print("✓ All scriptTasks have scriptVersion v3")

# 7. Superfluous gateway check (1 in, 1 out)
for gw in proc.findall('bpmn:exclusiveGateway', NS):
    inc = len(gw.findall('bpmn:incoming', NS))
    out = len(gw.findall('bpmn:outgoing', NS))
    if inc == 1 and out == 1:
        errors.append(f"SUPERFLUOUS_GATEWAY: {gw.get('id')} has 1 in, 1 out")
print("✓ No superfluous gateways")

if errors:
    print("\nERRORS:")
    for e in errors:
        print(f"  ✗ {e}")
else:
    print("\n✓ Structural checklist PASSED — no errors")
PYEOF
